package thaumcraft.verification;

import java.nio.file.*;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.components.*;
import net.minecraft.client.gui.screens.inventory.*;
import net.minecraft.world.item.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
import thaumcraft.client.*;
import thaumcraft.network.ClientKnowledge;
import thaumcraft.registry.*;

@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class InterfaceFollowupClient {
    private static int tick,waited;private static CreativeModeInventoryScreen creative;private static ThaumonomiconScreen book;private static final List<String> checks=new ArrayList<>();private static final List<String> sounds=new ArrayList<>();private static long scannedSequence;private static int catalogPool;
    private static java.lang.reflect.Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
    private static void check(boolean pass,String label){if(!pass)throw new AssertionError(label);checks.add(label);}
    private static boolean await(boolean ready){if(ready){waited=0;return false;}if(++waited<220){tick--;return true;}throw new AssertionError("native update timeout stage "+tick);}
    private static int left(Object screen)throws Exception{return field(AbstractContainerScreen.class,"leftPos").getInt(screen);}
    private static int top(Object screen)throws Exception{return field(AbstractContainerScreen.class,"topPos").getInt(screen);}
    private static void point(Minecraft mc,double x,double y)throws Exception{var screen=mc.screen;var m=MouseHandler.class.getDeclaredMethod("onMove",long.class,double.class,double.class);m.setAccessible(true);double xx=x*mc.getWindow().getScreenWidth()/screen.width,yy=y*mc.getWindow().getScreenHeight()/screen.height;m.invoke(mc.mouseHandler,mc.getWindow().getWindow(),xx,yy);m.invoke(mc.mouseHandler,mc.getWindow().getWindow(),xx,yy);}
    private static void click(Minecraft mc,double x,double y,int button)throws Exception{point(mc,x,y);double scale=mc.getWindow().getGuiScaledWidth()/(double)mc.screen.width;mc.screen.mouseClicked(x*scale,y*scale,button);mc.screen.mouseReleased(x*scale,y*scale,button);}
    private static void shot(Minecraft mc,String name)throws Exception{try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/r3/evidence/"+name+".png"));}check(org.lwjgl.opengl.GL11.glGetError()==0,name+" renders without GL errors");}
    private static void refresh()throws Exception{var method=CreativeModeInventoryScreen.class.getDeclaredMethod("refreshSearchResults");method.setAccessible(true);method.invoke(creative);}
    private static void target(Minecraft mc,Item item)throws Exception{int i=0;while(i<creative.getMenu().items.size()&&!creative.getMenu().items.get(i).is(item))i++;check(i<creative.getMenu().items.size(),"creative catalog contains requested native item "+item);int rows=Math.max(1,(creative.getMenu().items.size()+8)/9-5);float scroll=Math.clamp((i/9)/(float)rows,0,1);field(CreativeModeInventoryScreen.class,"scrollOffs").setFloat(creative,scroll);creative.getMenu().scrollTo(scroll);var slot=creative.getMenu().slots.stream().limit(45).filter(s->s.getItem().is(item)).findFirst().orElseThrow();point(mc,left(creative)+slot.x+8,top(creative)+slot.y+8);}
    @SubscribeEvent public static void sound(net.neoforged.neoforge.client.event.sound.PlaySoundEvent event){if("interface-followup-live".equals(System.getProperty("thaumcraft.r3.phase"))&&event.getSound()!=null)sounds.add(event.getSound().getLocation().toString());}
    @SubscribeEvent public static void tooltip(RenderTooltipEvent.Pre event){if(!"interface-followup-live".equals(System.getProperty("thaumcraft.r3.phase")))return;if(event.getComponents().stream().anyMatch(c->c instanceof AspectTooltipRenderer))hasAspectTooltip=true;}
    private static boolean hasAspectTooltip;private static int primaryLearnBefore;
    @SubscribeEvent public static void run(ClientTickEvent.Post event)throws Exception{
        if(!"interface-followup-live".equals(System.getProperty("thaumcraft.r3.phase")))return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.getOverlay()!=null)return;if(tick==0&&(mc.screen!=null||!mc.player.getMainHandItem().is(R2Content.BOOK.get())||!ClientKnowledge.snapshot().scanned(thaumcraft.api.knowledge.PlayerKnowledge.ScanKind.OBJECT).contains("minecraft:water")))return;
        try{
            ++tick;
            if(tick==20){mc.getToasts().clear();var tab=net.minecraft.core.registries.BuiltInRegistries.CREATIVE_MODE_TAB.get(net.minecraft.resources.ResourceLocation.parse("thaumcraft:thaumcraft"));field(CreativeModeInventoryScreen.class,"selectedTab").set(null,tab);creative=new CreativeModeInventoryScreen(mc.player,mc.level.enabledFeatures(),true);mc.setScreen(creative);var group=(Button)field(CreativeModeInventoryScreen.class,"tcGroupButton").get(creative);check(group.getWidth()==20&&group.getHeight()==18,"group mode control is a compact 20x18 tab");var search=(EditBox)field(CreativeModeInventoryScreen.class,"searchBox").get(creative);check(search.getX()==left(creative)+82&&search.getWidth()==88,"search text aligns one pixel inside its native frame");var buttons=(List<Button>)field(CreativeModeInventoryScreen.class,"tcSectionButtons").get(creative);check(buttons.size()==8&&buttons.stream().allMatch(b->b.visible),"all eight category shortcuts are visible");for(int i=0;i<8;i++)check(!CreativeSectionIcons.section(i).isEmpty(),"category shortcut "+i+" has a real native item icon");check(CreativeSectionIcons.tab().is(R2Content.WAND.get()),"default main tab icon is the iron-capped wooden wand");}
            if(tick==25)shot(mc,"interface-creative-materials");
            if(tick==27){var buttons=(List<Button>)field(CreativeModeInventoryScreen.class,"tcSectionButtons").get(creative);buttons.get(7).onPress();var sections=(CreativeSections)field(CreativeModeInventoryScreen.class,"tcSections").get(creative);int header=sections.headers().entrySet().stream().filter(e->e.getValue()==7).findFirst().orElseThrow().getKey();float scroll=field(CreativeModeInventoryScreen.class,"scrollOffs").getFloat(creative);int row=Math.round(scroll*Math.max(0,(creative.getMenu().items.size()+8)/9-5));check(header>=row&&header<row+5,"forbidden shortcut scrolls its header into view");point(mc,left(creative)-11,top(creative)+24+7*14+7);}
            if(tick==32){shot(mc,"interface-creative-forbidden");thaumcraft.config.ThaumcraftClientConfig.CREATIVE_TAB_ICON.set(thaumcraft.config.ThaumcraftClientConfig.CreativeTabIcon.THAUMONOMICON);check(CreativeSectionIcons.tab().is(R2Content.BOOK.get()),"config switches main tab icon to Thaumonomicon");thaumcraft.config.ThaumcraftClientConfig.CREATIVE_TAB_ICON.set(thaumcraft.config.ThaumcraftClientConfig.CreativeTabIcon.THAUMOMETER);check(CreativeSectionIcons.tab().is(R2Content.THAUMOMETER.get()),"config switches main tab icon to Thaumometer");thaumcraft.config.ThaumcraftClientConfig.CREATIVE_TAB_ICON.set(thaumcraft.config.ThaumcraftClientConfig.CreativeTabIcon.WAND);mc.player.closeContainer();mc.setScreen(null);mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
            if(tick==45){if(await(mc.screen instanceof ThaumonomiconScreen))return;book=(ThaumonomiconScreen)mc.screen;check(sounds.contains("thaumcraft:page"),"opening the book reaches the original page sound");int before=sounds.size();click(mc,left(book)-12,top(book)+3*24+12,0);check(sounds.subList(before,sounds.size()).contains("thaumcraft:page"),"category switching uses page turning rather than camera click");var d=ClientKnowledge.definitions().get("PAVEWARD");field(ThaumonomiconScreen.class,"panX").setDouble(book,-d.column()*24);field(ThaumonomiconScreen.class,"panY").setDouble(book,-d.row()*24);var nx=ThaumonomiconScreen.class.getDeclaredMethod("nodeX",thaumcraft.api.research.ResearchDefinition.class);var ny=ThaumonomiconScreen.class.getDeclaredMethod("nodeY",thaumcraft.api.research.ResearchDefinition.class);nx.setAccessible(true);ny.setAccessible(true);click(mc,(int)nx.invoke(book,d),(int)ny.invoke(book,d),0);}
            if(tick==55){if(await(ClientKnowledge.snapshot().completedResearch().contains("PAVEWARD")))return;check(sounds.contains("thaumcraft:learn"),"aspect-purchased research plays the same learning sound as a discovery");var current=field(ResearchCompletionOverlay.class,"research").get(null);check(current!=null&&((thaumcraft.api.research.ResearchDefinition)current).key().equals("PAVEWARD"),"aspect purchase starts the upper-left research completion popup");}
            if(tick==57){mc.getToasts().clear();}
            if(tick==60){shot(mc,"interface-secondary-research-popup");field(ThaumonomiconScreen.class,"selected").set(book,ClientKnowledge.definitions().get("ASPECTS"));var pages=ThaumonomiconScreen.class.getDeclaredMethod("pages");pages.setAccessible(true);var list=(List<?>)pages.invoke(book);int i=0;for(;i<list.size();i++){var aspects=list.get(i).getClass().getDeclaredMethod("aspects");aspects.setAccessible(true);if(((List<?>)aspects.invoke(list.get(i))).contains(thaumcraft.api.aspects.Aspects.WATER))break;}check(i<list.size(),"aspect book includes Aqua page");field(ThaumonomiconScreen.class,"spread").setInt(book,i/2);}
            if(tick==65){var hovers=(List<?>)field(ThaumonomiconScreen.class,"pageHovers").get(book);for(var h:hoverTools(hovers)){if(h.aspect==thaumcraft.api.aspects.Aspects.WATER&&h.width>=32){point(mc,h.x+12,h.y+12);break;}}var method=ThaumonomiconScreen.class.getDeclaredMethod("knownSources",thaumcraft.api.aspects.Aspect.class);method.setAccessible(true);var sources=(List<?>)method.invoke(book,thaumcraft.api.aspects.Aspects.WATER);boolean water=false;for(var s:sources){var f=s.getClass().getDeclaredMethod("fluid");f.setAccessible(true);water|=f.invoke(s).equals("water");}check(water,"scanned water is retained as a fluid source, not discarded as a missing item");}
            if(tick==70){shot(mc,"interface-aqua-source-highlight");mc.player.closeContainer();mc.setScreen(null);mc.player.connection.sendCommand("r3research table");}
            if(tick==80){if(await(mc.screen instanceof ResearchScreen))return;check(true,"native research table opens for visual checks");}
            if(tick==120){mc.getToasts().clear();}
            if(tick==125){shot(mc,"interface-parchment-runes");mc.player.connection.sendCommand("r3research complete");}
            if(tick==135){if(await(thaumcraft.items.ResearchNotes.read(((ResearchScreen)mc.screen).getMenu().table.getItem(1)).complete))return;}
            if(tick==140){shot(mc,"interface-completed-links");mc.player.closeContainer();mc.setScreen(null);mc.player.connection.sendCommand("gamemode survival");}
            if(tick==145){if(await(!mc.gameMode.hasInfiniteItems()))return;mc.setScreen(new InventoryScreen(mc.player));var slot=mc.player.inventoryMenu.slots.stream().filter(s->s.getItem().is(R2Content.THAUMOMETER.get())).findFirst().orElseThrow();click(mc,left(mc.screen)+slot.x+8,top(mc.screen)+slot.y+8,0);}
            if(tick==150){if(await(mc.player.containerMenu.getCarried().is(R2Content.THAUMOMETER.get())))return;var slot=mc.player.inventoryMenu.slots.stream().filter(s->s.getItem().is(R3Equipment.KNOWLEDGE_FRAGMENT.get())).findFirst().orElseThrow();point(mc,left(mc.screen)+slot.x+8,top(mc.screen)+slot.y+8);}
            if(tick==158)shot(mc,"interface-inventory-scanning");
            if(tick==180){if(await(ScanUi.scanned(new ItemStack(R3Equipment.KNOWLEDGE_FRAGMENT.get()))))return;check(hasAspectTooltip,"cursor scanner displays full native tooltip followed by aspect component without Shift");scannedSequence=field(ScanUi.class,"sequence").getLong(null);shot(mc,"interface-inventory-scanned");}
            if(tick==185)scannedSequence=field(ScanUi.class,"sequence").getLong(null);
            if(tick==190)check(field(ScanUi.class,"sequence").getLong(null)==scannedSequence,"known hovered item sends no further scan requests");
            if(tick==195)mc.player.connection.sendCommand("gamemode creative");
            if(tick==200){if(await(mc.gameMode.hasInfiniteItems()))return;mc.player.closeContainer();mc.setScreen(null);field(CreativeModeInventoryScreen.class,"selectedTab").set(null,net.minecraft.core.registries.BuiltInRegistries.CREATIVE_MODE_TAB.get(net.minecraft.resources.ResourceLocation.parse("minecraft:search")));creative=new CreativeModeInventoryScreen(mc.player,mc.level.enabledFeatures(),true);mc.setScreen(creative);var search=(EditBox)field(CreativeModeInventoryScreen.class,"searchBox").get(creative);search.setValue("stone");refresh();creative.getMenu().setCarried(new ItemStack(R2Content.THAUMOMETER.get()));catalogPool=ClientKnowledge.snapshot().pool(thaumcraft.api.aspects.Aspects.EARTH);target(mc,Items.STONE);}
            if(tick==207)shot(mc,"interface-catalog-scanning");
            if(tick==230){if(await(ScanUi.scanned(new ItemStack(Items.STONE))))return;check(ClientKnowledge.snapshot().pool(thaumcraft.api.aspects.Aspects.EARTH)>catalogPool,"hovering an unowned catalog item commits a real server scan reward");shot(mc,"interface-catalog-scanned");scannedSequence=field(ScanUi.class,"sequence").getLong(null);}
            if(tick==235)scannedSequence=field(ScanUi.class,"sequence").getLong(null);
            if(tick==250){check(field(ScanUi.class,"sequence").getLong(null)==scannedSequence,"known catalog item is not rescanned after completion");mc.player.closeContainer();mc.setScreen(null);mc.player.connection.sendCommand("r3research supplies");mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
            if(tick==265){if(await(mc.screen instanceof ThaumonomiconScreen&&mc.player.getInventory().items.stream().anyMatch(s->s.is(Items.PAPER))))return;book=(ThaumonomiconScreen)mc.screen;field(ThaumonomiconScreen.class,"category").set(book,"ALCHEMY");var d=ClientKnowledge.definitions().get("NITOR");field(ThaumonomiconScreen.class,"panX").setDouble(book,-d.column()*24);field(ThaumonomiconScreen.class,"panY").setDouble(book,-d.row()*24);primaryLearnBefore=(int)sounds.stream().filter(n->n.equals("thaumcraft:learn")).count();click(mc,left(book)+128,top(book)+108,0);}
            if(tick==280){if(await(field(ThaumonomiconScreen.class,"popupUntil").getLong(book)>0))return;check(sounds.stream().filter(n->n.equals("thaumcraft:learn")).count()>primaryLearnBefore,"successful note issuance uses learning sound rather than writing");check(mc.player.getInventory().items.stream().anyMatch(s->{var n=thaumcraft.items.ResearchNotes.read(s);return n!=null&&n.key.equals("NITOR");}),"learning sound follows actual issued note");}
            if(tick==285){shot(mc,"interface-issued-note-learning-sound");finish(mc,true,null);}
        }catch(Throwable failure){failure.printStackTrace();finish(mc,false,failure.toString());}
    }
    private record Hover(int x,int y,int width,thaumcraft.api.aspects.Aspect aspect){}
    private static List<Hover> hoverTools(List<?> source)throws Exception{var result=new ArrayList<Hover>();for(var h:source){var c=h.getClass();var x=c.getDeclaredMethod("x");var y=c.getDeclaredMethod("y");var w=c.getDeclaredMethod("width");var a=c.getDeclaredMethod("aspect");for(var m:List.of(x,y,w,a))m.setAccessible(true);result.add(new Hover((int)x.invoke(h),(int)y.invoke(h),(int)w.invoke(h),(thaumcraft.api.aspects.Aspect)a.invoke(h)));}return result;}
    private static void finish(Minecraft mc,boolean pass,String error)throws Exception{var result=new LinkedHashMap<String,Object>();result.put("passed",pass);result.put("count",checks.size());result.put("checks",checks);result.put("sounds",sounds);if(error!=null)result.put("error",error);Files.writeString(Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/r3/evidence/interface-followup-client.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result));mc.stop();}
}
